// helper to build a tip
const tip = (t: string, paras: string[], visuals?: VisualSlot[]): Tip => ({ title: t, paragraphs: paras, visuals: visuals || [] });
const V = (label: string, src?: string): VisualSlot => ({ label, src });

// Rich-tip helpers: build a tip from an ordered mix of blocks.
const tipB = (t: string, blocks: TipBlock[], visuals?: VisualSlot[]): Tip => ({ title: t, paragraphs: [], blocks, visuals: visuals || [] });
const PB = (text: string): TipBlock => ({ kind: "p", text });
const LB = (...items: string[]): TipBlock => ({ kind: "list", items });
const QB = (text: string): TipBlock => ({ kind: "quote", text });
const BOX = (heading: string, text: string, href?: string): TipBlock => ({ kind: "callout", heading: heading || undefined, text, href });
// Action / result callouts (distinct icon + colour).
const DO = (heading: string, text: string): TipBlock => ({ kind: "callout", heading, text, variant: "do" });
const RES = (heading: string, text: string): TipBlock => ({ kind: "callout", heading, text, variant: "result" });
const TARGET = (heading: string, text: string): TipBlock => ({ kind: "callout", heading, text, icon: "target" });
const EX = (heading: string, text: string): TipBlock => ({ kind: "callout", heading, text, tone: "amber", icon: "bulb" });
const CASE = (heading: string, text: string, href: string): TipBlock => ({ kind: "callout", heading, text, href, tone: "pink", icon: "spark" });
const EG = (text: string): TipBlock => ({ kind: "example", text });
const SUB = (text: string): TipBlock => ({ kind: "subheading", text });
const TBL = (headers: string[], rows: string[][], caption?: string): TipBlock => ({ kind: "table", headers, rows, caption });

type StepContent = { title: string; teaser: string; keyStat: KeyStat; partners: Partner[] };

